script:
test("drops the lowest of four homework scores and returns 70.5", function () {
  assert.deepEqual(code.finalGrade({ homework: [90, 80, 70, 100], quizzes: [80, 70], exam: [60] }), {
    homeworkAverage: 90,
    quizAverage: 75,
    examScore: 60,
    final: 70.5,
    display: "70.5",
    droppedHomework: 70
  });
});
test("does not drop homework when only three scores are given and returns 68.5", function () {
  assert.deepEqual(code.finalGrade({ homework: [90, 80, 70], quizzes: [80, 70], exam: [60] }), {
    homeworkAverage: 80,
    quizAverage: 75,
    examScore: 60,
    final: 68.5,
    display: "68.5",
    droppedHomework: null
  });
});
test("counts empty quizzes as zero and shows 48.0", function () {
  assert.deepEqual(code.finalGrade({ homework: [90, 80, 70, 100], quizzes: [], exam: [60] }), {
    homeworkAverage: 90,
    quizAverage: 0,
    examScore: 60,
    final: 48.0,
    display: "48.0",
    droppedHomework: 70
  });
});
test("rounds a non-half final of 75.983 up to 76.0", function () {
  assert.deepEqual(code.finalGrade({ homework: [80, 80, 85], quizzes: [70, 71], exam: [77] }), {
    homeworkAverage: 245 / 3,
    quizAverage: 70.5,
    examScore: 77,
    final: 76.0,
    display: "76.0",
    droppedHomework: null
  });
});
test("drops the lowest of five homework scores and returns 69.5", function () {
  assert.deepEqual(code.finalGrade({ homework: [50, 40, 10, 30, 20], quizzes: [100, 50], exam: [80] }), {
    homeworkAverage: 35,
    quizAverage: 75,
    examScore: 80,
    final: 69.5,
    display: "69.5",
    droppedHomework: 10
  });
});
test("drops the first score when it is the lowest of four homework scores", function () {
  assert.deepEqual(code.finalGrade({ homework: [10, 90, 80, 70], quizzes: [40, 60], exam: [55] }), {
    homeworkAverage: 80,
    quizAverage: 50,
    examScore: 55,
    final: 58.5,
    display: "58.5",
    droppedHomework: 10
  });
});
test("drops the last score when it is the lowest of four homework scores", function () {
  assert.deepEqual(code.finalGrade({ homework: [90, 80, 70, 10], quizzes: [40, 60], exam: [48] }), {
    homeworkAverage: 80,
    quizAverage: 50,
    examScore: 48,
    final: 55.0,
    display: "55.0",
    droppedHomework: 10
  });
});
test("drops only one homework score when the lowest score is tied", function () {
  assert.deepEqual(code.finalGrade({ homework: [70, 90, 70, 80], quizzes: [60], exam: [50] }), {
    homeworkAverage: 80,
    quizAverage: 60,
    examScore: 50,
    final: 59.0,
    display: "59.0",
    droppedHomework: 70
  });
});
test("averages a single score in each category and does not drop it", function () {
  assert.deepEqual(code.finalGrade({ homework: [88], quizzes: [76], exam: [91] }), {
    homeworkAverage: 88,
    quizAverage: 76,
    examScore: 91,
    final: 85.9,
    display: "85.9",
    droppedHomework: null
  });
});
test("counts empty homework as zero and returns 60.5", function () {
  assert.deepEqual(code.finalGrade({ homework: [], quizzes: [80, 90], exam: [70] }), {
    homeworkAverage: 0,
    quizAverage: 85,
    examScore: 70,
    final: 60.5,
    display: "60.5",
    droppedHomework: null
  });
});
test("counts an empty exam as zero and does not drop two homework scores", function () {
  assert.deepEqual(code.finalGrade({ homework: [80, 90], quizzes: [70], exam: [] }), {
    homeworkAverage: 85,
    quizAverage: 70,
    examScore: 0,
    final: 38.0,
    display: "38.0",
    droppedHomework: null
  });
});
test("returns zero when homework quizzes and the exam are all empty", function () {
  assert.deepEqual(code.finalGrade({ homework: [], quizzes: [], exam: [] }), {
    homeworkAverage: 0,
    quizAverage: 0,
    examScore: 0,
    final: 0.0,
    display: "0.0",
    droppedHomework: null
  });
});
test("averages four quizzes and does not drop the lowest quiz", function () {
  assert.deepEqual(code.finalGrade({ homework: [50], quizzes: [100, 80, 20, 60], exam: [70] }), {
    homeworkAverage: 50,
    quizAverage: 65,
    examScore: 70,
    final: 64.5,
    display: "64.5",
    droppedHomework: null
  });
});
test("keeps homework scores of 0 1 and 100 and rounds 86.733 down to 86.7", function () {
  assert.deepEqual(code.finalGrade({ homework: [0, 100, 1], quizzes: [100], exam: [100] }), {
    homeworkAverage: 101 / 3,
    quizAverage: 100,
    examScore: 100,
    final: 86.7,
    display: "86.7",
    droppedHomework: null
  });
});
test("averages five quizzes and does not drop the lowest quiz", function () {
  assert.deepEqual(code.finalGrade({ homework: [99], quizzes: [10, 40, 30, 20, 50], exam: [99] }), {
    homeworkAverage: 99,
    quizAverage: 30,
    examScore: 99,
    final: 78.3,
    display: "78.3",
    droppedHomework: null
  });
});
test("throws when the input has an unknown field named bonus", function () {
  assert.throws(function () {
    code.finalGrade({ homework: [90], quizzes: [80], exam: [70], bonus: 1 });
  }, /unknown field: bonus/);
});
